import { createHash, randomBytes, timingSafeEqual } from 'node:crypto';
import http from 'node:http';
import { readFileSync } from 'node:fs';

// Keep these origins aligned with platform/src/auth/config/cloudFormation/config.json.
const DESTINATIONS = {
  prod: { api: 'https://api.zira.us', auth: 'https://zira.auth.us-west-2.amazoncognito.com' },
  integ: { api: 'https://integ.api.zira.us', auth: 'https://zira-integ.auth.eu-west-1.amazoncognito.com' }
};

// Generated by the plugin builder. Standalone toolkit/developer sources allow both profiles.
// Invalid policies fail closed; environment variables cannot override an artifact's policy.
try {
  const policy = JSON.parse(readFileSync(new URL('./distribution-policy.json', import.meta.url), 'utf8'));
  if (!Array.isArray(policy.profiles) || !policy.profiles.length || policy.profiles.some(p => !Object.hasOwn(DESTINATIONS, p)))
    throw new Error('Invalid packaged profile policy');
  for (const profile of Object.keys(DESTINATIONS)) if (!policy.profiles.includes(profile)) delete DESTINATIONS[profile];
} catch (error) { if (error.code !== 'ENOENT') throw error; }

const destinations = (profile) => {
  if (!Object.hasOwn(DESTINATIONS, profile)) throw new Error(`Unknown profile "${profile}". Use an allowed profile for this build.`);
  return DESTINATIONS[profile];
};

const endpoint = (value, field) => {
  let url;
  try { url = new URL(value); } catch { throw new Error(`Invalid Zira ${field}`); }
  if (url.protocol !== 'https:' || url.username || url.password || url.port || url.search || url.hash)
    throw new Error(`Untrusted Zira ${field}`);
  return url;
};

export const validateApiBase = (value, profile) => {
  const url = endpoint(value, 'apiBaseUrl');
  const allowed = profile === undefined ? Object.values(DESTINATIONS) : [destinations(profile)];
  if (url.pathname !== '/' || !allowed.some(d => d.api === url.origin))
    throw new Error('Untrusted Zira apiBaseUrl');
  return url.origin;
};

export const validateOAuthEndpoint = (value, field, profile) => {
  const url = endpoint(value, field);
  const allowed = profile === undefined ? Object.values(DESTINATIONS) : [destinations(profile)];
  const pathname = field === 'authorizationEndpoint' ? '/oauth2/authorize' : '/oauth2/token';
  if (url.pathname !== pathname || !allowed.some(d => d.auth === url.origin))
    throw new Error(`Untrusted Zira ${field}`);
  return url.href;
};

const validateCallback = value => {
  let url;
  try { url = new URL(value); } catch { throw new Error('Invalid Zira redirectUri'); }
  if (url.protocol !== 'http:' || url.hostname !== 'localhost' || url.username || url.password || url.search || url.hash)
    throw new Error('Zira redirectUri must use an HTTP localhost callback');
  return value;
};

const jsonFromResponse = async (response, description) => {
  const text = await response.text();
  let body;
  try {
    body = text ? JSON.parse(text) : {};
  } catch {
    throw new Error(`${description} returned invalid JSON (HTTP ${response.status})`);
  }
  if (!response.ok) {
    const oauthError = typeof body.error === 'string' ? body.error : body.error?.message;
    const detail = body.error_description || oauthError || body.message || response.statusText;
    throw new Error(`${description} failed: ${detail} (HTTP ${response.status})`);
  }
  return body;
};

export const fetchAgentConfig = async ({
  profile = 'prod',
  fetchImpl = globalThis.fetch
} = {}) => {
  // Environment overrides must not redirect discovery or choose another OAuth client.
  const discoveryUrl = `${destinations(profile).api}/auth/agent-config`;

  const response = await fetchImpl(discoveryUrl, {
    headers: { Accept: 'application/json' },
    redirect: 'error'
  });
  const responseBody = await jsonFromResponse(response, 'Agent configuration request');
  const config = responseBody.data && typeof responseBody.data === 'object'
    ? responseBody.data
    : responseBody;
  const requiredStrings = ['apiBaseUrl', 'authorizationEndpoint', 'clientId', 'redirectUri', 'tokenEndpoint'];
  for (const field of requiredStrings) {
    if (typeof config[field] !== 'string' || !config[field]) {
      throw new Error(`Agent configuration is missing ${field}`);
    }
  }
  if (!Array.isArray(config.scopes) || config.scopes.some((scope) => typeof scope !== 'string')) {
    throw new Error('Agent configuration is missing scopes');
  }

  return {
    apiBaseUrl: validateApiBase(config.apiBaseUrl, profile),
    authorizationEndpoint: validateOAuthEndpoint(config.authorizationEndpoint, 'authorizationEndpoint', profile),
    clientId: config.clientId,
    redirectUri: validateCallback(config.redirectUri),
    scopes: config.scopes,
    tokenEndpoint: validateOAuthEndpoint(config.tokenEndpoint, 'tokenEndpoint', profile)
  };
};

export const createPkce = () => {
  const verifier = randomBytes(48).toString('base64url');
  const challenge = createHash('sha256').update(verifier).digest('base64url');
  return { challenge, verifier };
};

export const createState = () => randomBytes(32).toString('base64url');

export const authorizationUrl = (config, { challenge, state, nonce, promptLogin = false }) => {
  const url = new URL(validateOAuthEndpoint(config.authorizationEndpoint, 'authorizationEndpoint'));
  validateCallback(config.redirectUri);
  url.searchParams.set('client_id', config.clientId);
  url.searchParams.set('response_type', 'code');
  url.searchParams.set('redirect_uri', config.redirectUri);
  url.searchParams.set('scope', config.scopes.join(' '));
  url.searchParams.set('state', state);
  if (nonce) {
    url.searchParams.set('nonce', nonce);
  }
  url.searchParams.set('code_challenge_method', 'S256');
  url.searchParams.set('code_challenge', challenge);
  if (promptLogin) {
    url.searchParams.set('prompt', 'login');
  }
  return url.toString();
};

const sameState = (actual, expected) => {
  if (!actual) return false;
  const actualBuffer = Buffer.from(actual);
  const expectedBuffer = Buffer.from(expected);
  if (actualBuffer.length !== expectedBuffer.length) return false;
  return timingSafeEqual(actualBuffer, expectedBuffer);
};

const escapeHtml = (value) => String(value)
  .replaceAll('&', '&amp;')
  .replaceAll('<', '&lt;')
  .replaceAll('>', '&gt;')
  .replaceAll('"', '&quot;')
  .replaceAll("'", '&#39;');

const callbackHtml = (successful, message) => `<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width">
<title>Zira CLI login</title><style>body{font:16px system-ui;max-width:38rem;margin:12vh auto;padding:2rem;color:#17202a}main{border:1px solid #d7dbdd;border-radius:12px;padding:2rem}h1{font-size:1.4rem}</style></head>
<body><main><h1>${successful ? 'Zira login complete' : 'Zira login failed'}</h1><p>${escapeHtml(message)}</p><p>You can close this window.</p></main></body></html>`;

const approvalHtml = (userName, continuePath, approvalToken) => `<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width">
<title>Continue to Zira agent</title><style>body{font:16px system-ui;max-width:38rem;margin:12vh auto;padding:2rem;color:#17202a}main{border:1px solid #d7dbdd;border-radius:12px;padding:2rem}h1{font-size:1.4rem}button{border:0;border-radius:8px;padding:.8rem 1rem;background:#17202a;color:white;font:inherit;font-weight:600;cursor:pointer}</style></head>
<body><main><h1>Continue to Zira agent</h1><p>Zira has authenticated this browser session.</p>
<form method="get" action="${escapeHtml(continuePath)}"><input type="hidden" name="approval" value="${escapeHtml(approvalToken)}">
<button type="submit">Continue as ${escapeHtml(userName)}</button></form></main></body></html>`;

export const startCallbackServer = async ({ redirectUri, expectedState, timeoutMs = 300_000 }) => {
  const redirect = new URL(redirectUri);
  if (redirect.protocol !== 'http:' || redirect.hostname !== 'localhost') {
    throw new Error('The OAuth redirect URI must use http://localhost');
  }

  let settleCode;
  let settleApproval;
  let callbackResponse;
  let codeSettled = false;
  let approvalSettled = false;
  let approvalShown = false;
  const approvalToken = createState();
  const continuePath = redirect.pathname === '/'
    ? '/continue'
    : `${redirect.pathname.replace(/\/$/, '')}/continue`;
  const codeResult = new Promise((resolve, reject) => {
    settleCode = { resolve, reject };
  });
  const approvalResult = new Promise((resolve, reject) => {
    settleApproval = { resolve, reject };
  });
  approvalResult.catch(() => undefined);

  const server = http.createServer((request, response) => {
    const requestUrl = new URL(request.url || '/', redirect.origin);

    if (request.method === 'GET' && requestUrl.pathname === continuePath) {
      const suppliedApproval = requestUrl.searchParams.get('approval');
      if (!approvalShown || approvalSettled || !sameState(suppliedApproval, approvalToken)) {
        response.writeHead(400, { 'Content-Type': 'text/plain; charset=utf-8' });
        response.end('Invalid or expired login approval');
        return;
      }
      approvalSettled = true;
      response.writeHead(200, { 'Content-Type': 'text/html; charset=utf-8' });
      response.end(callbackHtml(true, 'You can return to your agent.'));
      settleApproval.resolve();
      return;
    }

    if (request.method !== 'GET' || requestUrl.pathname !== redirect.pathname || codeSettled) {
      response.writeHead(404, { 'Content-Type': 'text/plain; charset=utf-8' });
      response.end('Not found');
      return;
    }

    const error = requestUrl.searchParams.get('error');
    const errorDescription = requestUrl.searchParams.get('error_description');
    const code = requestUrl.searchParams.get('code');
    const state = requestUrl.searchParams.get('state');

    if (error) {
      codeSettled = true;
      response.writeHead(400, { 'Content-Type': 'text/html; charset=utf-8' });
      response.end(callbackHtml(false, 'Authorization was not completed.'));
      settleCode.reject(new Error(`Authorization failed: ${errorDescription || error}`));
    } else if (!sameState(state, expectedState)) {
      codeSettled = true;
      response.writeHead(400, { 'Content-Type': 'text/html; charset=utf-8' });
      response.end(callbackHtml(false, 'The security state did not match.'));
      settleCode.reject(new Error('Authorization failed because the OAuth state did not match'));
    } else if (!code) {
      codeSettled = true;
      response.writeHead(400, { 'Content-Type': 'text/html; charset=utf-8' });
      response.end(callbackHtml(false, 'No authorization code was returned.'));
      settleCode.reject(new Error('Authorization callback did not contain a code'));
    } else {
      codeSettled = true;
      callbackResponse = response;
      settleCode.resolve(code);
    }
  });

  server.on('clientError', (_error, socket) => socket.end('HTTP/1.1 400 Bad Request\r\n\r\n'));

  await new Promise((resolve, reject) => {
    server.once('error', reject);
    server.listen(Number(redirect.port), '127.0.0.1', resolve);
  });

  const timeout = setTimeout(() => {
    const error = new Error('Timed out waiting for browser login');
    if (!codeSettled) {
      codeSettled = true;
      settleCode.reject(error);
    } else if (!approvalSettled) {
      approvalSettled = true;
      settleApproval.reject(error);
    }
    server.close();
  }, timeoutMs);
  timeout.unref();

  const close = () => {
    clearTimeout(timeout);
    server.close();
  };

  return {
    wait: codeResult,
    confirm: (userName) => {
      if (!callbackResponse || callbackResponse.writableEnded) {
        throw new Error('The browser login callback is no longer available');
      }
      approvalShown = true;
      callbackResponse.writeHead(200, { 'Content-Type': 'text/html; charset=utf-8' });
      callbackResponse.end(approvalHtml(userName, continuePath, approvalToken));
      callbackResponse = undefined;
      return approvalResult;
    },
    fail: (message = 'The token exchange could not be completed.') => {
      if (callbackResponse && !callbackResponse.writableEnded) {
        callbackResponse.writeHead(400, { 'Content-Type': 'text/html; charset=utf-8' });
        callbackResponse.end(callbackHtml(false, message));
        callbackResponse = undefined;
      }
    },
    close
  };
};

const postTokenRequest = async (tokenEndpoint, parameters, fetchImpl = globalThis.fetch) => {
  const response = await fetchImpl(validateOAuthEndpoint(tokenEndpoint, 'tokenEndpoint'), {
    method: 'POST',
    headers: {
      Accept: 'application/json',
      'Content-Type': 'application/x-www-form-urlencoded'
    },
    body: new URLSearchParams(parameters),
    redirect: 'error'
  });
  return jsonFromResponse(response, 'OAuth token request');
};

const normalizeTokens = (tokens, previousRefreshToken) => {
  if (!tokens.id_token || !tokens.access_token) {
    throw new Error('OAuth token response did not include ID and access tokens');
  }
  const refreshToken = tokens.refresh_token || previousRefreshToken;
  if (!refreshToken) {
    throw new Error('OAuth token response did not include a refresh token');
  }
  return {
    accessToken: tokens.access_token,
    expiresAt: Date.now() + Number(tokens.expires_in || 3600) * 1000,
    idToken: tokens.id_token,
    refreshToken,
    tokenType: tokens.token_type || 'Bearer',
    updatedAt: new Date().toISOString()
  };
};

export const exchangeAuthorizationCode = async (config, code, verifier, fetchImpl = globalThis.fetch) => {
  validateCallback(config.redirectUri);
  const tokens = await postTokenRequest(config.tokenEndpoint, {
    grant_type: 'authorization_code',
    client_id: config.clientId,
    code,
    redirect_uri: config.redirectUri,
    code_verifier: verifier
  }, fetchImpl);
  return normalizeTokens(tokens);
};

export const refreshTokens = async (profile, fetchImpl = globalThis.fetch) => {
  if (!profile.refreshToken) {
    throw new Error('No refresh token is available; run `zira login` again');
  }
  const tokens = await postTokenRequest(profile.tokenEndpoint, {
    grant_type: 'refresh_token',
    client_id: profile.clientId,
    refresh_token: profile.refreshToken
  }, fetchImpl);
  return { ...profile, ...normalizeTokens(tokens, profile.refreshToken) };
};

export const decodeJwt = (token) => {
  try {
    const [, payload] = token.split('.');
    return JSON.parse(Buffer.from(payload, 'base64url').toString('utf8'));
  } catch {
    return {};
  }
};

export const tokenNeedsRefresh = (profile, skewMs = 60_000) => {
  const claims = decodeJwt(profile.idToken || '');
  const expiresAt = Number(claims.exp) * 1000 || Number(profile.expiresAt) || 0;
  return expiresAt <= Date.now() + skewMs;
};
